H.background();
// Gravitational field:  g = G * M / r^2  (points toward the mass)
// Field strength weakens with the square of distance from the source.
const G = 6.674e-11;
const M = P.M * 1e24;   // source mass in units of 10^24 kg
const cx = H.W * 0.5, cy = H.H * 0.52;
const scale = 36;       // px per 10^6 m
// the central mass (field source)
H.circle(cx, cy, 14, { fill: H.colors.accent2 });
H.text("M", cx - 5, cy + 5, { color: H.colors.bg, size: 13, weight: 700 });
// a ring of fixed field arrows pointing inward, length ~ g(r) (inverse square)
const rings = [2.2, 3.6, 5.2];
for (let k = 0; k < rings.length; k++) {
  const rPix = rings[k] * scale;
  const rMeters = rings[k] * 1e6;
  const g = G * M / (rMeters * rMeters);          // m/s^2
  const len = H.clamp(g * 1.1e6, 8, 46);          // visual length ~ g
  for (let i = 0; i < 12; i++) {
    const ang = i / 12 * H.TAU;
    const ox = cx + rPix * Math.cos(ang), oy = cy + rPix * Math.sin(ang);
    const ix = cx + (rPix - len) * Math.cos(ang), iy = cy + (rPix - len) * Math.sin(ang);
    H.arrow(ox, oy, ix, iy, { color: H.colors.accent, width: 1.6, head: 6 });
  }
}
